function isInFrustum( object ) {

    var distance, matrix = object.matrixWorld,
    scaleX,scaleY,scaleZ,parent,radius;
    scaleX = object.scale.x;
    scaleY = object.scale.y;
    scaleZ = object.scale.z;
    parent = object.parent;
    while (parent ) {
        scaleX = scaleX * parent.scale.x;
        scaleY = scaleY * parent.scale.y;
        scaleZ = scaleZ * parent.scale.z;
        parent = parent.parent;
    } 
    radius = - object.geometry.boundingSphere.radius * Math.max(scaleX , Math.max( scaleY , scaleZ  ) );

    for ( var i = 0; i < 6; i ++ ) {

        distance = _frustum[ i ].x * matrix.n14 + _frustum[ i ].y * matrix.n24 + _frustum[ i ].z * matrix.n34 + _frustum[ i ].w;
        if ( distance <= radius ){
            console.log("false");
            return false;
        }

    }

    return true;

};
